changeSet.sql:
ALTER TABLE financial.wallet_entries
    ADD COLUMN id_transfer bigint;
ALTER TABLE financial.wallet_entries
    ADD CONSTRAINT fk_transfers_on_wallet_entries FOREIGN KEY (id_transfer) REFERENCES financial.transfers (id) ON DELETE SET NULL;
CREATE INDEX ix_wallet_entries_on_transfer ON financial.wallet_entries (id_transfer);
ALTER TABLE financial.wallet_entries
    DROP CONSTRAINT ck_wallet_entries_on_origin;
ALTER TABLE financial.wallet_entries
    ADD CONSTRAINT ck_wallet_entries_on_origin CHECK (origin IN ('INCOME', 'EXPENSE', 'REVERSAL', 'ADJUSTMENT', 'TRANSFER'));

rollback.sql:
DELETE FROM financial.wallet_entries WHERE origin IN ('ADJUSTMENT', 'TRANSFER');
ALTER TABLE financial.wallet_entries
    DROP CONSTRAINT ck_wallet_entries_on_origin;
ALTER TABLE financial.wallet_entries
    ADD CONSTRAINT ck_wallet_entries_on_origin CHECK (origin IN ('INCOME', 'EXPENSE', 'REVERSAL'));
DROP INDEX financial.ix_wallet_entries_on_transfer;
ALTER TABLE financial.wallet_entries
    DROP CONSTRAINT fk_transfers_on_wallet_entries;
ALTER TABLE financial.wallet_entries
    DROP COLUMN id_transfer;
